function InvestMainNewDialogCell:__init()

end

function InvestMainNewDialogCell:__delete()

end

function InvestMainNewDialogCell:Awake()
    KTool.SetActive(self.Button1.gameObject,false)
    KTool.SetActive(self.Button2.gameObject,false)
    KTool.SetActive(self.UIFX_InvestMainDialog_Cell.gameObject,false)
    self:AddUIClick()
end

function InvestMainNewDialogCell:AddUIClick()
    SetButtonAction(self.Button1.gameObject,Bind(self,self.OnDrawRewardClick))
    SetButtonAction(self.Button2.gameObject,Bind(self,self.OnDrawRewardClick))
end

function InvestMainNewDialogCell:SetCallBackAndIndex(index,callBack)
    self.index = index
    self.callBack = callBack
end

function InvestMainNewDialogCell:RefreshShow(isFirstPay,dojo,rewards,isPlay)
    self:RemoveWaitCo()
    self.dojo = dojo
    self.isFirstPay = isFirstPay
    KTool.SetActive(self.UIFX_Received.gameObject,false)
    CfUtils.FillText(self.TxtNumber,self.index)
    CfUtils.PlayAnimation(self.controller.gameObject,"InvestMainType2Dialog_Cell_Idle")
    if isFirstPay then
        local signDay = dojo.overseaNewFirstGift.signDayNumber
        local isGet = self:IsGetReward()
        self:SetGetState(isGet)
        CfUtils.SetUISwitchImage(self.TxtDay,1)
        self.TxtNumber.Status = 1
        if not isGet then
            ---说明签到天数超过3天了 直接全显示领取
            KTool.SetActive(self.FloorReceived.gameObject,false)
            if signDay >= self.index then
                self:SetGetBtnStatus(false)
                KTool.SetActive(self.FloorReceived.gameObject,true)
                CfUtils.PlayAnimation(self.controller.gameObject,"InvestMainType2Dialog_Cell_Reveive")
            --[[    self.waitCo = cs_coroutine.start(function()
                    coroutine.yield(CS.UnityEngine.WaitForSeconds(0.05 * self.index))
                    KTool.SetActive(self.UIFX_Received.gameObject,true)
                end)]]

                CfUtils.SetUISwitchImage(self.TxtDay,2)
                self.TxtNumber.Status = 2
            else
                self:SetGetBtnStatus(true)
                if signDay + 1 == self.index then
                    self:StartCountDown()
                elseif signDay + 1 < self.index then
                    KTool.SetActive(self.FloorReceived.gameObject,false)
                end
            end
        else
            KTool.SetActive(self.FloorReceived.gameObject,false)
        end
    else
        self:SetGetState(false)
        self:SetGetBtnStatus(true)
        self:SetCountDownStatus(false)
    end
    self:SetRewardShow(rewards)
end

function InvestMainNewDialogCell:StartCountDown()
    local remainTime = isSet(self.dojo.overseaNewFirstGift,"nextReceiveTime") and (self.dojo.overseaNewFirstGift.nextReceiveTime - os.time()) or 0
    self:RemoveTimer()
    if remainTime > 0 then
        CfUtils.FillText(self.TxtTime,CfUtils.GetTimeHMS2(checkNumber(remainTime)))
        self:SetCountDownStatus(true)
        self.Timer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
            if count > 0 then
                CfUtils.FillText(self.TxtTime,CfUtils.GetTimeHMS2(checkNumber(count)))
            else
                self:SetCountDownStatus(false)
                self:RemoveTimer()
            end
        end, remainTime, false, true)
    else
        self:SetCountDownStatus(false)
    end
end

function InvestMainNewDialogCell:RemoveTimer()
    if self.Timer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
        self.Timer = nil
    end
end

function InvestMainNewDialogCell:SetCountDownStatus(state)
    KTool.SetActive(self.CountdownGroup.gameObject,state)
end

function InvestMainNewDialogCell:SetGetBtnStatus(status)
    KTool.SetActive(self.Button2.gameObject,status)
    KTool.SetActive(self.Button1.gameObject,not status)
    --KTool.SetActive(self.UIFX_InvestMainDialog_Cell.gameObject,not status)
end

function InvestMainNewDialogCell:SetRewardShow(rewards)
    if rewards and #rewards > 0 then
        ---@type CommonGoodsList
        local rewardEnv = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsList)
        local rewards = checkTable(rewards)
        rewardEnv:FreshBaseUI(rewards)
    end
end

function InvestMainNewDialogCell:SetGetState(isGet)
    KTool.SetActive(self.FloorFinish.gameObject,isGet)
    KTool.SetActive(self.OperatingState.gameObject,not isGet)
end

function InvestMainNewDialogCell:IsGetReward()
    local haveGetDay = self.dojo.overseaNewFirstGift.receiveId
    if haveGetDay[tostring(self.index)] then
        return true
    end
    return false
end

function InvestMainNewDialogCell:OnDrawRewardClick()
    if not self.isFirstPay then
        if self.index == 1 then
            GameUtils.Toast(localize("购买后，即可领取奖励"))
        else
            GameUtils.Toast(localize("购买后，累计登录_day_日，即可领取奖励",{_day_ = self.index}))
        end
        return
    end
    local isGet = self:IsGetReward()
    if isGet then return end
    local signDay = self.dojo.overseaNewFirstGift.signDayNumber
    if signDay < self.index then
        if self.index == 1 then
            GameUtils.Toast(localize("购买后，即可领取奖励"))
        else
            GameUtils.Toast(localize("购买后，累计登录_day_日，即可领取奖励",{_day_ = self.index}))
        end
        return
    end
    if self.callBack then
        self.callBack(self.index)
    end
end

function InvestMainNewDialogCell:RemoveWaitCo()
    if self.waitCo then
        cs_coroutine.stop(self.waitCo)
        self.waitCo = nil
    end
end

function InvestMainNewDialogCell:OnDestroy()
    --self:RemoveWaitCo()
    self:RemoveTimer()
    self.dojo = nil
    self.index = nil
    self.callBack = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return InvestMainNewDialogCell